/** One palette's S-52 colour table, as the subset of tokens we use. */
export interface S52Colors {
  /** No data covered by any chart cell. */
  NODTA: string;
  /** Depth: intertidal / dries. */
  DEPIT: string;
  /** Depth: very shallow (above shallow contour). */
  DEPVS: string;
  /** Depth: medium shallow (shallow…safety). */
  DEPMS: string;
  /** Depth: medium deep (safety…deep). */
  DEPMD: string;
  /** Depth: deep water. */
  DEPDW: string;
  /** Safety contour line. */
  DEPSC: string;
  /** Ordinary depth contour line. */
  DEPCN: string;
  /** Land area fill. */
  LANDA: string;
  /** Grey outline (dredged area boundary etc.). */
  CHGRF: string;
  /** Chart black (default point symbols, shallow soundings). */
  CHBLK: string;
  /** Chart grey (unsurveyed-area edge). */
  CHGRD: string;
  /** Magenta glow (radar-conspicuous coastline underlay). */
  CHMGF: string;
  /** Chart brown (shoreline-construction area tint). */
  CHBRN: string;
  /** Land-structure boundary brown (SILTNK/PRDARE's non-conspicuous LS boundary — a genuinely distinct token from CHBRN, not an alias: checked directly against all 5 upstream <color-table>s before assuming otherwise, unlike TRFCF==CHMGF). */
  LANDF: string;
  /** Coastline / shoreline constructions. */
  CSTLN: string;
  /** Soundings deeper than the safety depth (deemphasized). */
  SNDG1: string;
  /** Soundings at or shallower than the safety depth. */
  SNDG2: string;
  /** Red light (flare tint reference / all-round ring). */
  LITRD: string;
  /** Green light. */
  LITGN: string;
  /** White/yellow/amber light. */
  LITYW: string;
  /** Chart magenta (restricted-area boundaries, default light colour). */
  CHMGD: string;
  /** Traffic/caution boundary (CTNARE). */
  TRFCD: string;
  /** Traffic separation zone fill (TSEZNE, AC(TRFCF,3) — ochartsng's AreaRule drops the trailing transparency arg and draws opaque like every other AC(), so this is a plain fill colour, not a wash). */
  TRFCF: string;
  /** Symbol outline (black on the day palette; light-ring halo). */
  OUTLW: string;
  /** User-info foreground: outlines and labels of overlays that are not chart data (AIS). Inverts — near-black rgb(7,7,7) on day, light grey rgb(43,48,48) at night. */
  UINFD: string;
  /** User-info background: the halo behind such an overlay. UINFD's other half, and it inverts with it — near-white rgb(212,234,238) on day, near-black rgb(7,7,7) at night. */
  UIBCK: string;
}

